WITH kept AS (SELECT s.* FROM accounts s WHERE EXISTS (SELECT 1 FROM transactions x WHERE x.account_id = s.id AND x.txn_time <= s.opened_date)) SELECT status, CASE WHEN balance >= 63000 THEN 'HIGH' ELSE 'LOW' END AS balance_tier, SUM(CASE WHEN account_type = 'CHECKING' THEN balance ELSE 0 END) AS checking_balance, COUNT(*) FILTER (WHERE account_type = 'SAVINGS') AS savings_rows, AVG(balance) AS avg_balance, MIN(balance) AS min_balance, SORT_ARRAY(COLLECT_SET(status)) AS status_list, ROUND(SUM(balance) / NULLIF(COUNT(CASE WHEN status = 'OPEN' THEN 1 END), 0), 2) AS balance_per_open FROM kept GROUP BY status, balance_tier ORDER BY balance_per_open DESC;
